/*
 * Blox UI — design tokens
 * ------------------------------------------------------------------
 * Every tone (brand, neutral, danger, success, warning) ships the same
 * five roles, so any component can be re-toned without new CSS:
 *   --bx-<tone>        solid fill
 *   --bx-<tone>-hover  solid fill, hovered
 *   --bx-<tone>-fg     text on the solid fill
 *   --bx-<tone>-soft   tinted background
 *   --bx-<tone>-text   coloured text on bg / soft
 * Override any --bx-* variable to theme the whole library.
 */

@custom-variant dark (&:where(.dark, .dark *));

:root {
  /* Surfaces */
  --bx-bg: oklch(0.99 0.003 270);
  --bx-fg: oklch(0.21 0.02 270);
  --bx-surface: oklch(1 0 0);
  --bx-sunken: oklch(0.97 0.005 270);
  --bx-muted: oklch(0.5 0.02 270);
  --bx-border: oklch(0.91 0.008 270);
  --bx-border-strong: oklch(0.82 0.012 270);

  /* Tones */
  --bx-brand: oklch(0.55 0.22 275);
  --bx-brand-hover: oklch(0.49 0.22 275);
  --bx-brand-fg: oklch(1 0 0);
  --bx-brand-soft: oklch(0.95 0.035 275);
  --bx-brand-text: oklch(0.45 0.2 275);

  --bx-neutral: oklch(0.25 0.02 270);
  --bx-neutral-hover: oklch(0.34 0.02 270);
  --bx-neutral-fg: oklch(0.99 0 0);
  --bx-neutral-soft: oklch(0.95 0.005 270);
  --bx-neutral-text: oklch(0.3 0.02 270);

  --bx-danger: oklch(0.58 0.22 27);
  --bx-danger-hover: oklch(0.52 0.22 27);
  --bx-danger-fg: oklch(1 0 0);
  --bx-danger-soft: oklch(0.95 0.035 27);
  --bx-danger-text: oklch(0.48 0.19 27);

  --bx-success: oklch(0.56 0.15 155);
  --bx-success-hover: oklch(0.5 0.15 155);
  --bx-success-fg: oklch(1 0 0);
  --bx-success-soft: oklch(0.95 0.045 155);
  --bx-success-text: oklch(0.42 0.12 155);

  --bx-warning: oklch(0.78 0.16 75);
  --bx-warning-hover: oklch(0.72 0.16 75);
  --bx-warning-fg: oklch(0.25 0.05 75);
  --bx-warning-soft: oklch(0.96 0.05 85);
  --bx-warning-text: oklch(0.48 0.11 70);

  /* Chart series: use in this order, never cycled. Validated for colour-blind separation. */
  --bx-chart-1: #2a78d6;
  --bx-chart-2: #eb6834;
  --bx-chart-3: #1baf7a;
  --bx-chart-4: #eda100;
  --bx-chart-5: #e87ba4;
  --bx-chart-6: #008300;
  --bx-chart-7: #6250d6;
  --bx-chart-8: #e34948;

  /* Shape, focus, elevation */
  --bx-ring: var(--bx-brand);
  --bx-radius: 0.625rem;
  --bx-shadow-raised: 0 1px 2px oklch(0.2 0.02 270 / 0.06),
    0 6px 20px -6px oklch(0.2 0.02 270 / 0.14);
}

.dark {
  --bx-bg: oklch(0.16 0.015 270);
  --bx-fg: oklch(0.96 0.005 270);
  --bx-surface: oklch(0.2 0.017 270);
  --bx-sunken: oklch(0.13 0.015 270);
  --bx-muted: oklch(0.7 0.02 270);
  --bx-border: oklch(0.3 0.02 270);
  --bx-border-strong: oklch(0.4 0.02 270);

  --bx-brand: oklch(0.68 0.19 275);
  --bx-brand-hover: oklch(0.74 0.17 275);
  --bx-brand-fg: oklch(0.15 0.03 275);
  --bx-brand-soft: oklch(0.3 0.08 275);
  --bx-brand-text: oklch(0.82 0.12 275);

  --bx-neutral: oklch(0.93 0.005 270);
  --bx-neutral-hover: oklch(1 0 0);
  --bx-neutral-fg: oklch(0.18 0.015 270);
  --bx-neutral-soft: oklch(0.27 0.017 270);
  --bx-neutral-text: oklch(0.92 0.005 270);

  --bx-danger: oklch(0.66 0.2 27);
  --bx-danger-hover: oklch(0.72 0.18 27);
  --bx-danger-fg: oklch(0.15 0.03 27);
  --bx-danger-soft: oklch(0.3 0.08 27);
  --bx-danger-text: oklch(0.82 0.11 27);

  --bx-success: oklch(0.7 0.15 155);
  --bx-success-hover: oklch(0.76 0.14 155);
  --bx-success-fg: oklch(0.15 0.03 155);
  --bx-success-soft: oklch(0.28 0.06 155);
  --bx-success-text: oklch(0.83 0.12 155);

  --bx-warning: oklch(0.8 0.15 80);
  --bx-warning-hover: oklch(0.85 0.14 80);
  --bx-warning-fg: oklch(0.2 0.04 80);
  --bx-warning-soft: oklch(0.3 0.06 80);
  --bx-warning-text: oklch(0.86 0.12 85);

  /* Chart series: use in this order, never cycled. Validated for colour-blind separation. */
  --bx-chart-1: #3987e5;
  --bx-chart-2: #d95926;
  --bx-chart-3: #199e70;
  --bx-chart-4: #c98500;
  --bx-chart-5: #d55181;
  --bx-chart-6: #008300;
  --bx-chart-7: #9085e9;
  --bx-chart-8: #e66767;

  --bx-shadow-raised: 0 1px 2px oklch(0 0 0 / 0.4),
    0 8px 24px -8px oklch(0 0 0 / 0.6);
}

/* Expose tokens as Tailwind utilities: bg-surface, text-muted, border-border … */
@theme inline {
  --color-bg: var(--bx-bg);
  --color-fg: var(--bx-fg);
  --color-surface: var(--bx-surface);
  --color-sunken: var(--bx-sunken);
  --color-muted: var(--bx-muted);
  --color-border: var(--bx-border);
  --color-border-strong: var(--bx-border-strong);
  --color-ring: var(--bx-ring);

  --color-brand: var(--bx-brand);
  --color-brand-hover: var(--bx-brand-hover);
  --color-brand-fg: var(--bx-brand-fg);
  --color-brand-soft: var(--bx-brand-soft);
  --color-brand-text: var(--bx-brand-text);

  --color-neutral: var(--bx-neutral);
  --color-neutral-hover: var(--bx-neutral-hover);
  --color-neutral-fg: var(--bx-neutral-fg);
  --color-neutral-soft: var(--bx-neutral-soft);
  --color-neutral-text: var(--bx-neutral-text);

  --color-danger: var(--bx-danger);
  --color-danger-hover: var(--bx-danger-hover);
  --color-danger-fg: var(--bx-danger-fg);
  --color-danger-soft: var(--bx-danger-soft);
  --color-danger-text: var(--bx-danger-text);

  --color-success: var(--bx-success);
  --color-success-hover: var(--bx-success-hover);
  --color-success-fg: var(--bx-success-fg);
  --color-success-soft: var(--bx-success-soft);
  --color-success-text: var(--bx-success-text);

  --color-warning: var(--bx-warning);
  --color-warning-hover: var(--bx-warning-hover);
  --color-warning-fg: var(--bx-warning-fg);
  --color-warning-soft: var(--bx-warning-soft);
  --color-warning-text: var(--bx-warning-text);

  --color-chart-1: var(--bx-chart-1);
  --color-chart-2: var(--bx-chart-2);
  --color-chart-3: var(--bx-chart-3);
  --color-chart-4: var(--bx-chart-4);
  --color-chart-5: var(--bx-chart-5);
  --color-chart-6: var(--bx-chart-6);
  --color-chart-7: var(--bx-chart-7);
  --color-chart-8: var(--bx-chart-8);

  --radius-sm: calc(var(--bx-radius) - 4px);
  --radius-md: calc(var(--bx-radius) - 2px);
  --radius-lg: var(--bx-radius);
  --radius-xl: calc(var(--bx-radius) + 4px);

  --shadow-raised: var(--bx-shadow-raised);
}

@layer base {
  * {
    border-color: var(--bx-border);
  }
  /* Tells the browser which theme is active, so native scrollbars, form controls
     and the page background follow it, and themes the scrollbar colours. */
  :root {
    color-scheme: light;
    scrollbar-color: var(--bx-border-strong) transparent;
  }
  .dark {
    color-scheme: dark;
  }
  body {
    background-color: var(--bx-bg);
    color: var(--bx-fg);
    -webkit-font-smoothing: antialiased;
  }
}

/* Motion */
@theme {
  --animate-pop-in: bx-pop-in 140ms cubic-bezier(0.16, 1, 0.3, 1);
  --animate-shimmer: bx-shimmer 1.6s ease-in-out infinite;
  --animate-indeterminate: bx-indeterminate 1.4s ease-in-out infinite;

  --animate-pop-out: bx-pop-out 100ms ease-in forwards;
  --animate-fade-in: bx-fade-in 160ms ease-out;
  --animate-fade-out: bx-fade-out 120ms ease-in forwards;
  --animate-dialog-in: bx-dialog-in 200ms cubic-bezier(0.16, 1, 0.3, 1);
  --animate-dialog-out: bx-dialog-out 130ms ease-in forwards;
  --animate-slide-in: bx-slide-in 260ms cubic-bezier(0.16, 1, 0.3, 1);
  --animate-slide-out: bx-slide-out 180ms ease-in forwards;

  --animate-collapse-down: bx-collapse-down 200ms ease-out;
  --animate-collapse-up: bx-collapse-up 180ms ease-out;

  /* Height comes from Radix: Accordion and Collapsible each set their own variable. */
  @keyframes bx-collapse-down {
    from {
      height: 0;
    }
    to {
      height: var(--radix-accordion-content-height, var(--radix-collapsible-content-height, auto));
    }
  }
  @keyframes bx-collapse-up {
    from {
      height: var(--radix-accordion-content-height, var(--radix-collapsible-content-height, auto));
    }
    to {
      height: 0;
    }
  }
  @keyframes bx-pop-out {
    to {
      opacity: 0;
      scale: 0.96;
    }
  }
  @keyframes bx-fade-in {
    from {
      opacity: 0;
    }
  }
  @keyframes bx-fade-out {
    to {
      opacity: 0;
    }
  }
  @keyframes bx-dialog-in {
    from {
      opacity: 0;
      scale: 0.95;
    }
  }
  @keyframes bx-dialog-out {
    to {
      opacity: 0;
      scale: 0.95;
    }
  }
  /* Direction comes from --bx-slide-x / --bx-slide-y set by the component. */
  @keyframes bx-slide-in {
    from {
      translate: var(--bx-slide-x, 0) var(--bx-slide-y, 0);
    }
  }
  @keyframes bx-slide-out {
    to {
      translate: var(--bx-slide-x, 0) var(--bx-slide-y, 0);
    }
  }
  @keyframes bx-pop-in {
    from {
      opacity: 0;
      scale: 0.96;
    }
  }
  @keyframes bx-shimmer {
    from {
      translate: -100% 0;
    }
    to {
      translate: 100% 0;
    }
  }
  @keyframes bx-indeterminate {
    from {
      translate: -100% 0;
    }
    to {
      translate: 250% 0;
    }
  }
}
